mapper.select:
SELECT distinct A.FINPROD_ID as finprodId, A.FINPROD_MARKET_ID as finprodMarketId, NVL(C.FINPROD_ABBR,A.FINPROD_ABBR) as finprodAbbr, B.BASE_RULE_ID as baseRuleId, B.COEFFICIENT as coefficient, B.RATE*100 as rate, CASE WHEN B.PUBLISH_TYPE = #{yesOrNo_Yes} THEN to_char(B.RATE_LOWER*100,'9999999990.99')||'~'||to_char(B.RATE_LIMIT*100,'9999999990.99') ELSE to_char(B.RATE*100,'9999999990.99') end as rates, B.SPREAD_RATE*100 as spreadRate, B.RESET_TYPE as resetType, B.EFF_DATE as effDate, B.RATE_TYPE as rateType, B.INDEX_ID as indexId, B.INDEX_SOURCE as indexSource, lay.PROD_STYLE prodStyle, PMSI.SEND_STATUS sendStatus, PMSI.SEND_REMARK sendRemark, CASE WHEN B.PUBLISH_TYPE = '01' THEN trim(to_char(B.RATE_LOWER*100,'9999999990.99'))||'%'||'~'||trim(to_char(B.RATE_LIMIT*100,'9999999990.99'))||'%' ELSE '' end as lowLimitRate, D.INVESTMENT_CYCLE investmentCycle
,B.BASE_RULE_TYPE baseRuleType
,NVL(A.P_FINPROD_ID,A.FINPROD_ID) pFinprodId
FROM FIN_PRODUCT A LEFT JOIN FIN_PRODUCT C ON A.P_FINPROD_ID = C.FINPROD_ID INNER JOIN PTL_MANAGE_OBJ /*ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.FINPROD_ID*/ /*mod by menghongwei 支持分档产品 20190626*/ ON ((A.p_Finprod_Id is null and PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.FINPROD_ID) or(A.p_Finprod_Id is not null and PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.P_FINPROD_ID))
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userName} INNER JOIN FIN_PRODUCT_ADD D ON A.FINPROD_ID = D.FINPROD_ID LEFT JOIN prd_layer_param lay ON A.FINPROD_ID = lay.FINPROD_ID , FIN_BASE_RULE_INFO B LEFT JOIN INF_FIN_BASE_RULE_INFO PMSI ON B.BASE_RULE_ID =PMSI.BASE_RULE_ID AND B.EFF_DATE = PMSI.EFF_DATE WHERE A.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F16,jdbcType=VARCHAR},#{FINPROD_TYPE_TG_F24,jdbcType=VARCHAR},#{FINPROD_TYPE_TG_F26,jdbcType=VARCHAR}) AND A.PROFIT_TYPE IN (#{PROFIT_TYPE_01,jdbcType=VARCHAR},#{PROFIT_TYPE_03,jdbcType=VARCHAR}) AND A.FINPROD_ID = B.FINPROD_ID AND B.BRANCH = 0 AND B.BASE_RULE_TYPE = #{BASE_RULE_TYPE_01,jdbcType=VARCHAR} AND ((D.DEAL_MODE = #{DISPOSE_PATTERN_10,jdbcType=VARCHAR} AND A.P_FINPROD_ID IS NOT NULL ) OR D.DEAL_MODE != #{DISPOSE_PATTERN_10,jdbcType=VARCHAR})
AND A.FINPROD_MARKET_ID IN
#{item}
AND lay.PROD_STYLE IN
#{item}
AND NVL(PMSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
AND B.EFF_DATE between to_date(#{sDate},'yyyy-mm-dd') and to_date(#{eDate},'yyyy-mm-dd')
#{key,jdbcType=VARCHAR}
ORDER BY A.FINPROD_ID ASC, B.EFF_DATE DESC
